 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    vals = {v for row in grid for v in row}
    background = max(vals, key=lambda v: sum(row.count(v) for row in grid))

    # A lone 1 is a ray source: mark it 4 and extend horizontally toward
    # the nearest non-background obstacle, stopping before that obstacle.
    ones = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    other = [(r, c) for r in range(h) for c in range(w)
             if grid[r][c] not in (background, 1)]
    if ones and other:
        for r, c in ones:
            obstacles = [oc for rr, oc in other if rr == r]
            if not obstacles:
                continue
            target = min(obstacles, key=lambda oc: abs(oc-c))
            direction = 1 if target > c else -1
            out[r][c] = 4
            cc = c + direction
            while 0 <= cc < w and cc != target:
                if grid[r][cc] not in (background, 1):
                    break
                out[r][cc] = 1
                cc += direction
        return out

    # Otherwise, the sparse 3s specify diagonal strokes. Turn each seed to 4,
    # then extend each slope detected in that arrangement with color 1.
    marks = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 3]
    if not marks:
        return out
    for r, c in marks:
        out[r][c] = 4
    slopes = set()
    for i, (r, c) in enumerate(marks):
        for rr, cc in marks[i+1:]:
            if abs(rr-r) == abs(cc-c) and rr != r:
                slopes.add(1 if (rr-r)*(cc-c) > 0 else -1)
    if not slopes:
        slopes = {1}
    # For each occupied diagonal (constant c-slope*r), fill its entire
    # in-bounds continuation, preserving 4 at original seed locations.
    for slope in slopes:
        offsets = {c - slope*r for r, c in marks}
        for offset in offsets:
            for r in range(h):
                c = slope*r + offset
                if 0 <= c < w and grid[r][c] != 1:
                    out[r][c] = 4 if grid[r][c] == 3 else 1
    return out

