    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    vals = {v for row in grid for v in row}
    bg = max(vals, key=lambda v: sum(row.count(v) for row in grid))
    counts = {v: sum(row.count(v) for row in grid) for v in vals}
    marker = 3 if 3 in vals else min((v for v in vals if v != bg), key=counts.get)
    seeds = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker]

    # Change source marks to the endpoint color, then extend each source along
    # its row/column toward the boundary guides, stopping at other objects.
    for r, c in seeds:
        out[r][c] = (marker + 1) % 10

    # Identify guide bars: repeated edge-colored cells on a grid boundary.
    edges = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg and grid[r][c] != marker and (r in (0, h-1) or c in (0, w-1)):
                edges.append((r, c, grid[r][c]))

    # For each seed, use its nearest boundary stroke to determine the ray axis.
    for r, c in seeds:
        if not edges:
            continue
        br, bc, _ = min(edges, key=lambda p: abs(p[0]-r) + abs(p[1]-c))
        dr = 0 if br == r else (1 if br > r else -1)
        dc = 0 if bc == c else (1 if bc > c else -1)
        # When guide lies diagonally away, propagate along its row/column axis;
        # simultaneous strokes on same edge indicate a horizontal/vertical fill.
        if dr and dc:
            if abs(br-r) >= abs(bc-c):
                dc = 0
            else:
                dr = 0
        if not dr and not dc:
            continue
        rr, cc = r + dr, c + dc
        while 0 <= rr < h and 0 <= cc < w:
            if grid[rr][cc] == bg:
                out[rr][cc] = marker
            elif grid[rr][cc] == marker:
                out[rr][cc] = (marker + 1) % 10
            else:
                break
            rr += dr
            cc += dc
    return out
