    marker = 3 if 3 in colors else 5
    seeds = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker]
    for r, c in seeds:
        out[r][c] = (marker + 1) % 10

    # Each seed produces a horizontal or vertical ray toward its associated
    # long edge guide. Rays of repeated seeds form two-cell-wide bands.
    # The guide colors are any non-background, non-seed objects on the edge.
    guides = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
              if grid[r][c] not in (bg, marker)
              and (r in (0, h - 1) or c in (0, w - 1))]
    if not guides:
        return out

    for r, c in seeds:
        gr, gc, _ = min(guides, key=lambda p: abs(p[0] - r) + abs(p[1] - c))
        # Determine ray axis from the relative position of source and guide.
        if abs(gc - c) >= abs(gr - r):
            dr, dc = 0, (1 if gc > c else -1)
        else:
            dr, dc = (1 if gr > r else -1), 0
        rr, cc = r + dr, c + dc
        while 0 <= rr < h and 0 <= cc < w:
            if grid[rr][cc] == bg:
                out[rr][cc] = marker
            elif grid[rr][cc] == marker:
                out[rr][cc] = (marker + 1) % 10
            else:
                break
            rr += dr
            cc += dc
    return out
