    marker = min((v for v in vals if v != bg), key=counts.get)
    seeds = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker]
    # The two horizontal edge bars define matching vertical ray bundles.
    top = [c for c, v in enumerate(grid[0]) if v != bg]
    bottom = [c for c, v in enumerate(grid[-1]) if v != bg]
    if top and bottom:
        top_lo, bottom_lo = min(top), min(bottom)
        # Each seed column is projected to the corresponding offset in the
        # opposite edge bar; original seed locations become endpoint color 4.
        active = set()
        for r, c in seeds:
            out[r][c] = (marker + 1) % 10
            if bottom_lo <= c <= max(bottom):
                active.add(c)
                counterpart = top_lo + (c - bottom_lo)
                if counterpart in top:
                    active.add(counterpart)
        for c in active:
            for r in range(1, h - 1):
                if grid[r][c] == bg:
                    out[r][c] = marker
        return out
    # Generic ray extension for edge guides oriented vertically.
    for r, c in seeds:
        out[r][c] = (marker + 1) % 10
        for dr, dc in ((0, -1), (0, 1), (-1, 0), (1, 0)):
            rr, cc = r + dr, c + dc
            while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == bg:
                out[rr][cc] = marker
                rr += dr
                cc += dc
    return out


